import {pickupConventions,conductorRoles} from '../wiring-generator/colours.mjs';
const root=document.querySelector('[data-conductor-reference]');
if(root){const table=document.createElement('table'),caption=document.createElement('caption');caption.textContent='Shared conductor conventions; verify the exact pickup model';table.append(caption);const head=document.createElement('thead'),row=document.createElement('tr');for(const text of ['Convention','Hot','Series link','Coil return','Shield']){const cell=document.createElement('th');cell.scope='col';cell.textContent=text;row.append(cell);}head.append(row);table.append(head);const body=document.createElement('tbody');for(const profile of Object.values(pickupConventions)){const row=document.createElement('tr');const values=profile.verified?[profile.label,profile.functions[conductorRoles.hot][1],profile.functions[conductorRoles.linkA][1]+' + '+profile.functions[conductorRoles.linkB][1],profile.functions[conductorRoles.ground][1],profile.functions[conductorRoles.shield][1]]:[profile.label,'Model-specific / unresolved','Verify exact documentation','Verify exact documentation','Verify exact documentation'];for(const [i,text] of values.entries()){const cell=document.createElement(i?'td':'th');if(!i)cell.scope='row';cell.textContent=text;row.append(cell);}body.append(row);}table.append(body);const wrapper=document.createElement('div');wrapper.className='knowledge-table';wrapper.tabIndex=0;wrapper.setAttribute('role','region');wrapper.setAttribute('aria-label','Pickup conductor reference, scroll horizontally if needed');wrapper.append(table);root.append(wrapper);}
